/**
 * squadData — Static squad data from CNF dataset (~328 clubs, 20 leagues)
 * Used for position-depth context in TM Scout without any network requests.
 */

export interface SquadPlayer {
  name: string
  pos: string
  mv: number
  age: number
  joined: number
}

export interface SquadContext {
  matchedClub: string
  posPlayers: SquadPlayer[]   // sorted by MV desc
  allPlayers: SquadPlayer[]
  squadAvgMv: number
  posAvgMv: number
  depth: number
  sellSignal: boolean          // high depth or player below pos avg
  buySignal: boolean           // thin coverage or pos far below squad avg
}

// Position mapping: TM abbreviations → CNF full position names
const POS_MAP: Record<string, string[]> = {
  GK:  ['Goalkeeper'],
  CB:  ['Centre-Back'],
  RB:  ['Right-Back'],
  LB:  ['Left-Back'],
  CDM: ['Defensive Midfield'],
  CM:  ['Central Midfield'],
  CAM: ['Attacking Midfield'],
  RW:  ['Right Winger'],
  LW:  ['Left Winger'],
  CF:  ['Centre-Forward', 'Second Striker'],
  ST:  ['Centre-Forward', 'Second Striker'],
  SS:  ['Second Striker'],
}

