// Build flat lookup: lowercase club name → { canonical, str }
const CLUB_LOOKUP = new Map<string, { name: string; str: string }>()
for (const leagueClubs of Object.values(RAW_LEAGUES)) {
  for (const [clubName, playerStr] of Object.entries(leagueClubs)) {
    CLUB_LOOKUP.set(clubName.toLowerCase(), { name: clubName, str: playerStr })
  }
}

function parsePlayers(str: string): SquadPlayer[] {
  return str.split('~').filter(s => s.trim()).flatMap(p => {
    const [name, pos, mv, age, joined] = p.split('|')
    if (!name?.trim() || !pos?.trim()) return []
    return [{ name: name.trim(), pos: pos.trim(), mv: parseFloat(mv) || 0, age: parseInt(age) || 0, joined: parseInt(joined) || 0 }]
  })
}

function avg(vals: number[]): number {
  return vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : 0
}

/** Strip common club name suffixes for fuzzy matching */
function normalize(name: string): string {
  return name.toLowerCase()
    .replace(/\b(fc|sc|ac|afc|bfc|fk|sk|cf|bv|vfl|vfb|rb|sv|rcd|rc|cd|ud|ca)\b/g, '')
    .replace(/[^a-z0-9]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
}

/** Find best matching club name in the dataset */
function findClub(query: string): string | null {
  if (!query) return null
  const q = query.toLowerCase().trim()
  // 1. Exact
  const exact = CLUB_LOOKUP.get(q)
  if (exact) return exact.name
  // 2. Normalized exact
  const qn = normalize(q)
  for (const [key, val] of CLUB_LOOKUP) {
    if (normalize(key) === qn) return val.name
  }
  // 3. Substring (shorter must be ≥4 chars to avoid false positives)
  for (const [key, val] of CLUB_LOOKUP) {
    if (key.length >= 4 && q.includes(key)) return val.name
    if (q.length >= 4 && key.includes(q)) return val.name
  }
  // 4. Normalized substring
  for (const [key, val] of CLUB_LOOKUP) {
    const kn = normalize(key)
    if (kn.length >= 4 && qn.includes(kn)) return val.name
    if (qn.length >= 4 && kn.includes(qn)) return val.name
  }
  return null
}

/**
 * Get squad context for a player: their club's depth at their position.
 * Pure synchronous — uses embedded dataset, no network calls.
 * @param clubName  Club name as returned by TM search
 * @param tmPos     TM position abbreviation ('CDM', 'ST', etc.)
 * @param playerMv  Player's MV in millions — used for sell-signal comparison
 */
export function getSquadContext(
  clubName: string,
  tmPos: string,
  playerMv?: number | null,
): SquadContext | null {
  const matchedClubName = findClub(clubName)
  if (!matchedClubName) return null
  const entry = CLUB_LOOKUP.get(matchedClubName.toLowerCase())
  if (!entry) return null
  const allPlayers = parsePlayers(entry.str)
  if (!allPlayers.length) return null
  const cnfPositions = POS_MAP[tmPos] ?? [tmPos]
  const posPlayers = allPlayers.filter(p => cnfPositions.includes(p.pos))
  const allMvs = allPlayers.filter(p => p.mv > 0).map(p => p.mv)
  const posMvs = posPlayers.filter(p => p.mv > 0).map(p => p.mv)
  const squadAvgMv = avg(allMvs)
  const posAvgMv = avg(posMvs)
  const sellSignal =
    posPlayers.length >= 3 ||
    (playerMv != null && posAvgMv > 0 && playerMv < posAvgMv * 0.8)
  const buySignal =
    posPlayers.length <= 1 ||
    (squadAvgMv > 0 && posAvgMv > 0 && posAvgMv < squadAvgMv * 0.65)
  return {
    matchedClub: matchedClubName,
    posPlayers: [...posPlayers].sort((a, b) => b.mv - a.mv),
    allPlayers,
    squadAvgMv,
    posAvgMv,
    depth: posPlayers.length,
    sellSignal,
    buySignal,
  }
}
